  v_new jsonb := '[{"code": "RD-A2-007", "text_type": "instruction", "situation": "bank", "title_ua": "Як відкрити рахунок у банку", "title_hr": "Kako otvoriti račun u banci", "body_hr": "Želite otvoriti tekući račun u našoj banci? Evo kako. Prvo dogovorite termin na našoj web-stranici ili telefonom. Ako ne želite čekati termin, dođite u banku, uzmite broj u redu i pričekajte na šalteru. Ponesite putovnicu ili osobnu iskaznicu, potvrdu o OIB-u i potvrdu o prebivalištu. Ako radite, ponesite i ugovor s poslodavcem. Službenik će vam objasniti koje račune imamo i koliko mjesečno košta svaki račun. Kad potpišete ugovor, karticu ćete primiti poštom za sedam do deset dana, a PIN dolazi u drugom pismu. Internetsko i mobilno bankarstvo možete uključiti odmah. Za sva pitanja nazovite nas ili pišite na našu e-poštu.", "body_ua": "Хочете відкрити поточний рахунок у нашому банку? Ось як. Спершу домовтеся про час на нашому сайті або телефоном. Якщо не хочете чекати запису, приходьте в банк, візьміть номерок у черзі й зачекайте біля віконця. Візьміть паспорт або посвідчення особи, довідку про OIB і довідку про місце проживання. Якщо працюєте, візьміть і договір з роботодавцем. Службовець пояснить вам, які рахунки в нас є і скільки щомісяця коштує кожен рахунок. Коли підпишете договір, картку отримаєте поштою за сім–десять днів, а PIN-код прийде в іншому листі. Інтернет-банкінг і мобільний банкінг можна ввімкнути одразу. З усіх питань телефонуйте нам або пишіть на нашу електронну пошту.", "glossary": [{"form": "želite", "lemma": "željeti", "ua": "бажати; хотіти", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: ви (і ввічливе «Ви»)"}, {"form": "otvoriti", "lemma": "otvoriti", "ua": "відчинити / відкрити", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)"}, {"form": "tekući", "lemma": "tekući račun", "ua": "поточний рахунок у банку", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), однина, ч. р.; частина виразу «tekući račun»"}, {"form": "račun", "lemma": "račun", "ua": "рахунок / чек", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "našoj", "lemma": "naš", "ua": "наш", "lesson": true, "pos": "присвійний займенник «наш»", "gram": "місцевий відмінок (де? про кого? про що?), однина, ж. р."}, {"form": "banci", "lemma": "banka", "ua": "банк", "lesson": true, "pos": "іменник, жіночий рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "evo", "lemma": "evo", "ua": "ось; ось тут", "lesson": false, "pos": "частка"}, {"form": "kako", "lemma": "kako", "ua": "як", "lesson": true, "pos": "питальний прислівник «як»"}, {"form": "prvo", "lemma": "prvo", "ua": "спочатку", "lesson": true, "pos": "прислівник «спочатку»"}, {"form": "dogovorite", "lemma": "dogovoriti se", "ua": "домовитися", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "termin", "lemma": "termin", "ua": "(вільний) час; запис (до лікаря, перукаря)", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false, "pos": "прийменник: + знахідний — куди? («na posao»), + місцевий — де? («na poslu»)"}, {"form": "web-stranici", "lemma": "web-stranica", "ua": "вебсайт", "lesson": true, "pos": "іменник, жіночий рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "ili", "lemma": "ili", "ua": "або; чи", "lesson": true, "pos": "сполучник"}, {"form": "telefonom", "lemma": "telefon", "ua": "телефон", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "орудний відмінок (ким? чим?), однина. «telefonom» — телефоном"}, {"form": "ako", "lemma": "ako", "ua": "якщо", "lesson": true, "pos": "сполучник"}, {"form": "ne", "lemma": "ne", "ua": "не (заперечення); ні", "lesson": true, "pos": "частка"}, {"form": "čekati", "lemma": "čekati", "ua": "чекати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)"}, {"form": "dođite", "lemma": "doći", "ua": "прийти", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "banku", "lemma": "banka", "ua": "банк", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "uzmite", "lemma": "uzeti", "ua": "взяти", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "broj", "lemma": "broj", "ua": "номер / число", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "redu", "lemma": "broj u redu", "ua": "номер у черзі", "lesson": true, "pos": "сталий вираз", "gram": "місцевий відмінок (де? про кого? про що?), однина; частина виразу «broj u redu»"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "pričekajte", "lemma": "pričekati", "ua": "почекати", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "šalteru", "lemma": "šalter", "ua": "віконце (в установі)", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "ponesite", "lemma": "ponijeti", "ua": "взяти із собою", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "putovnicu", "lemma": "putovnica", "ua": "закордонний паспорт", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "osobnu", "lemma": "osobna iskaznica", "ua": "посвідчення особи", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), однина, ж. р.; частина виразу «osobna iskaznica»"}, {"form": "iskaznicu", "lemma": "osobna iskaznica", "ua": "посвідчення особи", "lesson": true, "pos": "сталий вираз", "gram": "знахідний від